using System.Reflection;
using System.Linq;

var asm = Assembly.LoadFrom(
    Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
    ".nuget/packages/microsoft.agents.ai/1.13.0/lib/net10.0/Microsoft.Agents.AI.dll"));
// Find AgentResponse - it might be in a different assembly or have a different name
foreach (var t in asm.GetExportedTypes().Where(x => x.Name.Contains("Response") && !x.Name.Contains("Update") && !x.Name.Contains("Content") && !x.Name.Contains("Token")))
{
    Console.WriteLine($"{t.FullName}");
}
Console.WriteLine("---AIAgent base methods---");
var agent = asm.GetExportedTypes().First(x => x.Name == "AIAgent");
Console.WriteLine($"=== {agent.FullName} (abstract: {agent.IsAbstract}) base: {agent.BaseType?.Name} ===");
foreach (var p in agent.GetProperties(BindingFlags.Public|BindingFlags.Instance))
    Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
foreach (var m in agent.GetMethods(BindingFlags.Public|BindingFlags.Instance|BindingFlags.DeclaredOnly).Where(m => !m.IsSpecialName))
    Console.WriteLine($"  method {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p=>$"{p.ParameterType.Name} {p.Name}"))})");

// Also check the RunAsync return type
var runMethod = agent.GetMethods().First(m => m.Name == "RunAsync" && m.GetParameters().Length >= 2);
Console.WriteLine($"\nRunAsync returns: {runMethod.ReturnType.FullName}");
if (runMethod.ReturnType.IsGenericType) {
    var inner = runMethod.ReturnType.GetGenericArguments()[0];
    Console.WriteLine($"  Inner type: {inner.FullName}");
    foreach (var p in inner.GetProperties(BindingFlags.Public|BindingFlags.Instance))
        Console.WriteLine($"    prop {p.PropertyType.Name} {p.Name}");
}
