using System.Reflection;
using System.Linq;

var asm = Assembly.LoadFrom(
    Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
    ".nuget/packages/microsoft.agents.ai/1.13.0/lib/net10.0/Microsoft.Agents.AI.dll"));

// AIAgent is probably abstract
var agent = asm.GetExportedTypes().FirstOrDefault(x => x.Name == "AIAgent");
if (agent == null) {
    Console.WriteLine("AIAgent not found as exported type. Looking...");
    agent = asm.GetTypes().FirstOrDefault(x => x.Name == "AIAgent");
}
if (agent != null) {
    Console.WriteLine($"=== {agent.FullName} abstract={agent.IsAbstract} base={agent.BaseType?.Name} ===");
    foreach (var p in agent.GetProperties(BindingFlags.Public|BindingFlags.Instance|BindingFlags.FlattenHierarchy))
        Console.WriteLine($"  prop {p.PropertyType.Name} {p.Name}");
    foreach (var m in agent.GetMethods(BindingFlags.Public|BindingFlags.Instance|BindingFlags.DeclaredOnly).Where(m => !m.IsSpecialName))
        Console.WriteLine($"  method {m.ReturnType} {m.Name}({string.Join(", ", m.GetParameters().Select(p=>$"{p.ParameterType.Name}"))})");
}

// Check ChatClientAgent RunAsync
var cca = asm.GetExportedTypes().First(x => x.Name == "ChatClientAgent");
foreach (var m in cca.GetMethods(BindingFlags.Public|BindingFlags.Instance|BindingFlags.DeclaredOnly).Where(m => m.Name == "RunAsync" && !m.IsGenericMethod).Take(3))
{
    Console.WriteLine($"\n  RunAsync({string.Join(", ", m.GetParameters().Select(p=>$"{p.ParameterType.Name} {p.Name}"))}) -> {m.ReturnType}");
    if (m.ReturnType.IsGenericType) {
