using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---
var tools = new AIToolCollection
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// --- Create the agent ---
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    });

// --- Prompt the user ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching \"{topic}\"...\n");

// --- Run the agent ---
var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(
    $"""
    Research the following topic: "{topic}"

    Follow these steps:
    1. Perform 2-3 web searches with different queries to gather diverse information.
    2. Save the most important findings as notes using the SaveNote tool.
    3. Retrieve all your notes using GetNotes.
    4. Provide a comprehensive summary of your research findings, citing the sources.

    Be thorough but concise.
    """,
    session);

Console.WriteLine("--- Research Summary ---\n");
Console.WriteLine(response.Text);

if (response.Usage is { } usage)
{
    Console.WriteLine($"\n[Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}]");
}

// --- Clean up ---
rm -rf /tmp/inspect 2>/dev/null

// ===================== Tool implementations =====================

// In-memory notebook shared across tool invocations
var notebook = new List<(string Title, string Content, string Source)>();

[Description("Searches the web for information on a given query and returns relevant results.")]
static string WebSearch(
    [Description("The search query to look up on the web.")] string query)
{
    // Simulated web search results for demonstration.
    // In production, replace with a real search API (Bing, Google, etc.).
    var results = new StringBuilder();
    results.AppendLine($"Search results for: \"{query}\"\n");

    var simulatedResults = GetSimulatedResults(query);
    for (int i = 0; i < simulatedResults.Length; i++)
    {
        results.AppendLine($"[{i + 1}] {simulatedResults[i].title}");
        results.AppendLine($"    Source: {simulatedResults[i].url}");
        results.AppendLine($"    Snippet: {simulatedResults[i].snippet}");
        results.AppendLine();
    }

    return results.ToString();
}

[Description("Saves a research note with a title, content, and source URL for later reference.")]
string SaveNote(
    [Description("A short title for the note.")] string title,
    [Description("The content of the note.")] string content,
    [Description("The source URL where the information was found.")] string source)
{
    notebook.Add((title, content, source));
    return $"Note saved: \"{title}\" ({notebook.Count} total notes).";
}

[Description("Retrieves all saved research notes.")]
string GetNotes()
{
    if (notebook.Count == 0)
        return "No notes saved yet.";

    var sb = new StringBuilder();
    sb.AppendLine($"=== {notebook.Count} Saved Notes ===\n");
    for (int i = 0; i < notebook.Count; i++)
    {
        var (title, content, source) = notebook[i];
        sb.AppendLine($"Note {i + 1}: {title}");
        sb.AppendLine($"  Content: {content}");
        sb.AppendLine($"  Source: {source}");
        sb.AppendLine();
    }
    return sb.ToString();
}

static (string title, string url, string snippet)[] GetSimulatedResults(string query)
{
    var q = query.ToLowerInvariant();
    if (q.Contains("quantum computing"))
    {
        return
        [
            ("What is Quantum Computing? - IBM", "https://www.ibm.com/quantum/what-is-quantum-computing",
             "Quantum computing harnesses quantum-mechanical phenomena such as superposition and entanglement to process information in fundamentally new ways."),
            ("Quantum Computing Progress in 2025 - Nature", "https://www.nature.com/articles/quantum-2025",
             "Recent breakthroughs have pushed qubit counts beyond 1,000, with error correction reaching practical thresholds for the first time."),
            ("Applications of Quantum Computing - MIT Tech Review", "https://www.technologyreview.com/quantum-apps",
             "Quantum computers show promise in drug discovery, cryptography, optimization problems, and materials science simulations."),
        ];
    }

    if (q.Contains("artificial intelligence") || q.Contains(" ai ") || q.Contains("ai "))
    {
        return
        [
            ("State of AI Report 2025", "https://www.stateof.ai/2025",
             "AI capabilities have advanced rapidly, with large language models demonstrating reasoning and tool-use abilities that approach human-level performance."),
            ("AI in Healthcare - WHO Report", "https://www.who.int/ai-healthcare-2025",
             "Artificial intelligence is transforming diagnostics, drug development, and personalized medicine across global health systems."),
            ("AI Safety and Governance - OECD", "https://www.oecd.org/ai-governance",
             "International frameworks for AI governance continue to evolve, focusing on transparency, accountability, and risk management."),
        ];
    }

    // Generic fallback results
    return
    [
        ($"Overview of {query} - Wikipedia", $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
         $"A comprehensive overview of {query}, covering history, key concepts, and current developments."),
        ($"Latest Research on {query} - ScienceDirect", $"https://www.sciencedirect.com/search?query={Uri.EscapeDataString(query)}",
         $"Peer-reviewed research articles and systematic reviews related to {query}."),
        ($"{query}: Current Trends - Reuters", $"https://www.reuters.com/search/{Uri.EscapeDataString(query)}",
         $"News coverage and expert analysis on recent developments in {query}."),
    ];
}

