1. using System.ComponentModel;
2. using System.Text;
3. using Microsoft.Agents.AI;
4. using Microsoft.Extensions.AI;
5. using OpenAI;
6. 
7. // --- Configuration ---
8. var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
9.     ?? throw new InvalidOperationException(
10.         "Set the OPENAI_API_KEY environment variable before running.");
11. 
12. const string modelId = "gpt-4o-mini-2024-07-18";
13. 
14. // --- Build the IChatClient via MEAI abstraction ---
15. IChatClient chatClient = new OpenAIClient(apiKey)
16.     .GetChatClient(modelId)
17.     .AsIChatClient();
18. 
19. // --- Tool state ---
20. var notebook = new Notebook();
21. 
22. // --- Define tools ---
23. var tools = new List<AITool>
24. {
25.     AIFunctionFactory.Create(ResearchTools.WebSearch),
26.     AIFunctionFactory.Create(notebook.SaveNote),
27.     AIFunctionFactory.Create(notebook.GetNotes),
28. };
29. 
30. // --- Create the agent ---
31. var agent = new ChatClientAgent(
32.     chatClient,
33.     new ChatClientAgentOptions
34.     {
35.         Name = "ResearchAgent",
36.         Description = "An AI agent that researches topics by searching the web and taking notes.",
37.         ChatOptions = new ChatOptions
38.         {
39.             Temperature = 0f,
40.             MaxOutputTokens = 2048,
41.             Tools = [.. tools],
42.         },
43.     });
44. 
45. // --- Prompt the user ---
46. Console.WriteLine("=== Research Agent ===");
47. Console.Write("Enter a topic to research: ");
48. var topic = Console.ReadLine()?.Trim();
49. if (string.IsNullOrWhiteSpace(topic))
50. {
51.     Console.WriteLine("No topic provided. Exiting.");
52.     return;
53. }
54. 
55. Console.WriteLine($"\nResearching \"{topic}\"...\n");
56. 
57. // --- Run the agent ---
58. var session = await agent.CreateSessionAsync();
59. var response = await agent.RunAsync(
60.     $"""
61.     Research the following topic: "{topic}"
62. 
63.     Follow these steps:
64.     1. Perform 2-3 web searches with different queries to gather diverse information.
65.     2. Save the most important findings as notes using the SaveNote tool.
66.     3. Retrieve all your notes using GetNotes.
67.     4. Provide a comprehensive summary of your research findings, citing the sources.
68. 
69.     Be thorough but concise.
70.     """,
71.     session);
72. 
73. Console.WriteLine("--- Research Summary ---\n");
74. Console.WriteLine(response.Text);
75. 
76. if (response.Usage is { } usage)
77. {
78.     Console.WriteLine($"\n[Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}]");
79. }
80. 
81. // ===================== Note-taking tool =====================
