83. /// <summary>In-memory notebook shared across tool invocations.</summary>
84. sealed class Notebook
85. {
86.     private readonly List<(string Title, string Content, string Source)> _notes = [];
87. 
88.     [Description("Saves a research note with a title, content, and source URL for later reference.")]
89.     public string SaveNote(
90.         [Description("A short title for the note.")] string title,
91.         [Description("The content of the note.")] string content,
92.         [Description("The source URL where the information was found.")] string source)
93.     {
