95.         return $"Note saved: \"{title}\" ({_notes.Count} total notes).";
96.     }
97. 
98.     [Description("Retrieves all saved research notes.")]
99.     public string GetNotes()
100.     {
101.         if (_notes.Count == 0)
102.             return "No notes saved yet.";
103. 
104.         var sb = new StringBuilder();
